package com.bosskillmilestones;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("boss-kill-milestones")
public interface BossKillMilestonesConfig extends Config
{
	@ConfigSection(name = "Debug", description = "Testing and troubleshooting options", position = 100, closedByDefault = true)
	String debugSection = "debug";

	@ConfigSection(name = "Overlay", description = "On-screen counter, sidebar and visual effects", position = 50, closedByDefault = false)
	String overlaySection = "overlay";

	@ConfigItem(keyName = "personalGoalBasis", name = "Personal goal basis", description = "Choose whether your saved goal target uses all-time kills, this session or kills since activation. Session goals can be reached again each session.")
	default MilestoneBasis personalGoalBasis() { return MilestoneBasis.ALL_TIME; }

	@ConfigItem(keyName = "milestoneBasis", name = "Milestone basis", description = "Choose which kill count triggers milestone sounds and fireworks. All-time uses your known lifetime total, including loot estimates. Personal goals use their own basis setting.")
	default MilestoneBasis milestoneBasis() { return MilestoneBasis.SINCE_ACTIVATION; }

	enum MilestoneBasis
	{
		ALL_TIME("All-time kills"), SESSION("This session"), SINCE_ACTIVATION("Since activation");
		private final String label;
		MilestoneBasis(String label) { this.label = label; }
		@Override public String toString() { return label; }
		Integer count(int saved, int session, Integer total)
		{
			if (this == ALL_TIME) return total;
			return this == SESSION ? session : saved;
		}
	}

	@ConfigItem(keyName = "sessionCelebrations", name = "Session encouragement", description = "Optional short celebrations every 10 or 25 session kills per boss. Larger milestones and personal goals take priority.")
	default SessionEncouragement sessionCelebrations() { return SessionEncouragement.OFF; }

	@ConfigItem(keyName = "milestoneFireworks", name = "Milestone fireworks", section = overlaySection, position = 6, description = "Show a brief on-screen firework celebration when a milestone is reached. Larger milestones show bigger displays.")
	default boolean milestoneFireworks() { return true; }

	@ConfigItem(keyName = "overlayLayout", name = "Overlay layout", section = overlaySection, position = 1, description = "Full: all details. Compact: counters, next milestone and personal goal. Minimal: boss, session and saved counts, and next milestone.")
	default OverlayLayout overlayLayout() { return OverlayLayout.FULL; }

	enum OverlayLayout
	{
		FULL("Full"), COMPACT("Compact"), MINIMAL("Minimal");
		private final String label;
		OverlayLayout(String label) { this.label = label; }
		@Override public String toString() { return label; }
	}

	enum SessionEncouragement
	{
		OFF(0), EVERY_10(10), EVERY_25(25);
		final int interval;
		SessionEncouragement(int interval) { this.interval = interval; }
		@Override public String toString() { return interval == 0 ? "Off" : "Every " + interval + " kills"; }
	}
	@ConfigItem(keyName = "showGrindGoals", name = "Show goals on overlay", section = overlaySection, position = 2, description = "Show milestone progress, personal goals and cached friend comparisons in the Full layout.")
	default boolean showGrindGoals() { return true; }

	@ConfigItem(keyName = "friendHiscores", name = "Friends hiscore leaderboard", section = overlaySection, position = 5,
		description = "Look up your account and friends' public main-game boss totals. Requests send each username to the official hiscores service; results are cached for 10 minutes.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers")
	default boolean friendHiscores()
	{
		return false;
	}

	@ConfigItem(keyName = "alwaysOnGui", name = "Overlay always on", section = overlaySection, position = 3, description = "Keep the kill counter visible before your first kill and ignore the timeout. Show kill counter must also be enabled.")
	default boolean alwaysOnGui()
	{
		return false;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(keyName = "guiTimeoutMinutes", name = "Overlay timeout (minutes)", section = overlaySection, position = 4, description = "Hide the counter after this many minutes without a tracked kill. Ignored when Overlay always on is enabled.")
	default int guiTimeoutMinutes()
	{
		return 5;
	}

	@ConfigItem(keyName = "showOverlay", name = "Show kill counter", section = overlaySection, position = 0, description = "Show the current target, session kills, saved kills and lifetime total.")
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(keyName = "testGuard", name = "Varrock guard testing", description = "Track level 21 Guards in Varrock as a separate test target. Uses server loot even when boss loot backup is off.", section = debugSection, position = 0)
	default boolean testGuard()
	{
		return false;
	}

	@ConfigItem(keyName = "syncDiagnostics", name = "Debug lifetime sync", description = "Report unreadable Combat Achievements boss statistics in chat and the debug log. Turn off after troubleshooting.", section = debugSection, position = 1)
	default boolean syncDiagnostics() { return false; }

	@ConfigItem(keyName = "lootBackup", name = "Loot backup", description = "Count recognised boss server-loot events when a kill-count message is missing.")
	default boolean lootBackup()
	{
		return true;
	}

	@ConfigItem(keyName = "syncReminder", name = "Initial sync reminder", description = "Remind you at login until a boss total has been read from Combat Achievements.")
	default boolean syncReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "excludedBosses",
		name = "Excluded bosses",
		description = "Comma-separated boss names to exclude, matching the name shown in the kill-count message."
	)
	default String excludedBosses()
	{
		return "\n \n \n";
	}

	@ConfigItem(
		keyName = "playMilestoneSound",
		name = "Play milestone sound",
		description = "Play a celebratory sound when a boss milestone is reached."
	)
	default boolean playMilestoneSound()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "soundVolume", name = "Sound volume (%)", description = "Volume of milestone, personal goal and session sounds. 0 mutes; 100 is full volume. Applies to the next sound.")
	default int soundVolume() { return 100; }
}

package com.bosskillmilestones;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
	name = "Boss Milestones: Rank Among Friends",
	description = "Compare boss kills with friends, climb the leaderboard, and celebrate milestones.",
	tags = {"boss", "bossing", "pvm", "kills", "killcount", "kc", "milestones", "friends", "leaderboard",
		"hiscores", "highscores", "rankings", "goals", "progress", "tracker", "overlay", "jingles"}
)
public class BossKillMilestonesPlugin extends Plugin
{
	private static final String PROFILE_GROUP = "boss-kill-milestones";
	private final KillSignals signals = new KillSignals();
	private final OverlayActivity overlayActivity = new OverlayActivity(System::nanoTime);
	private final Map<String, Integer> lastLootTicks = new HashMap<>();
	private String profile;
	private boolean reminded;
	private String lastPanel;
	private final Map<String, Integer> sessionKills = new HashMap<>();
	private String activeBoss;
	private volatile Progress progress = new Progress("Waiting for a target", 0, 0, "Unknown");

	static final class Progress
	{
		final String name;
		final int session;
		final int saved;
		final String total;
		final int goal;
		final BossKillMilestonesConfig.MilestoneBasis basis;
		final BossKillMilestonesConfig.MilestoneBasis goalBasis;
		Progress(String name, int session, int saved, String total)
		{
			this(name, session, saved, total, 0);
		}
		Progress(String name, int session, int saved, String total, int goal)
		{
			this(name, session, saved, total, goal, BossKillMilestonesConfig.MilestoneBasis.SINCE_ACTIVATION);
		}
		Progress(String name, int session, int saved, String total, int goal, BossKillMilestonesConfig.MilestoneBasis basis)
		{
			this(name, session, saved, total, goal, basis, BossKillMilestonesConfig.MilestoneBasis.ALL_TIME);
		}
		Progress(String name, int session, int saved, String total, int goal, BossKillMilestonesConfig.MilestoneBasis basis,
			BossKillMilestonesConfig.MilestoneBasis goalBasis)
		{
			this.goalBasis = goalBasis;
			this.basis = basis;
			this.goal = goal;
			this.name = name;
			this.session = session;
			this.saved = saved;
			this.total = total;
		}
		Integer milestoneCount() { return basis.count(saved, session, GrindProgress.total(total)); }
		Integer goalCount() { return goalBasis.count(saved, session, GrindProgress.total(total)); }
		String goalCountText()
		{
			return goalBasis == BossKillMilestonesConfig.MilestoneBasis.ALL_TIME ? total : String.valueOf(goalCount());
		}
		String nextMilestoneText()
		{
			Integer count = milestoneCount();
			return count == null ? "Sync lifetime total" : (GrindProgress.nextMilestone(count) - count) + " away";
		}
	}

	Progress getProgress()
	{
		Progress current = progress;
		return new Progress(current.name, current.session, current.saved, current.total, current.goal, config.milestoneBasis(), config.personalGoalBasis());
	}

	boolean isCounterVisible()
	{
		return overlayActivity.visible(config.alwaysOnGui(), config.guiTimeoutMinutes());
	}
	static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
		"Your (?<prefix>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<suffix>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "(?:<col=[0-9a-f]{6}>|@.+?@)(?<total>[0-9,]+)</col>");

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BossKillMilestonesConfig config;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private BossMilestoneOverlay overlay;
	@Inject
	private FireworksOverlay fireworksOverlay;
	@Inject
	private MilestoneAudio milestoneAudio;
	@Inject
	private BossSidebar sidebar;

	@Override
	protected void startUp()
	{
		clearSession();
		milestoneAudio.start();
		overlayManager.add(overlay);
		overlayManager.add(fireworksOverlay);
		sidebar.start();
		log.debug("Boss Milestones: Rank Among Friends started");
	}

	@Override
	protected void shutDown()
	{
		sidebar.stop();
		overlayManager.remove(overlay);
		overlayManager.remove(fireworksOverlay);
		milestoneAudio.stop();
		clearSession();
		resetTransientState();
		profile = null;
		log.debug("Boss Milestones: Rank Among Friends stopped");
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!ready())
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		Matcher matcher = KILL_COUNT_PATTERN.matcher(event.getMessage());
		if (!matcher.find() || !isBossKillCountMessage(matcher.group("boss"), matcher.group("prefix"), matcher.group("suffix")))
		{
			return;
		}

		String bossName = BossNames.known(Text.removeTags(matcher.group("boss")));
		if (bossName == null)
		{
			return;
		}

		int total;
		try
		{
			total = Integer.parseInt(matcher.group("total").replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			log.debug("Could not parse kill count for {}", bossName);
			return;
		}

		String key = BossNames.key(bossName);
		Integer previousTotal = configManager.getRSProfileConfiguration(PROFILE_GROUP, "total-" + key, int.class);
		Integer lastChat = configManager.getRSProfileConfiguration(PROFILE_GROUP, "last-chat-" + key, int.class);
		// The old version stored only total-. Use it until the first new chat receipt.
		if (lastChat == null)
		{
			lastChat = previousTotal;
		}
		if (lastChat != null && total <= lastChat)
		{
			return;
		}
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "total-" + key, total);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "estimated-total-" + key, total);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "last-chat-" + key, total);
		if (isExcluded(bossName))
		{
			return;
		}
		if (signals.accept(key, false, client.getTickCount()))
		{
			recordKill(bossName, total, false);
		}
		activeBoss = bossName;
		refreshProgress();
	}

	private void recordKill(String bossName, Integer total, boolean estimated)
	{
		overlayActivity.killed();
		String key = BossNames.key(bossName);
		Integer savedMilestones = configManager.getRSProfileConfiguration(PROFILE_GROUP, "since-enabled-" + key, int.class);
		int sinceEnabled = savedMilestones == null ? 0 : savedMilestones;
		// Count the kill that generated this message, but don't replay kills from while
		// the plugin was off when the reported total jumps by more than one.
		sinceEnabled++;
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "since-enabled-" + key, sinceEnabled);
		sessionKills.merge(key, 1, Integer::sum);
		activeBoss = bossName;
		refreshProgress();

		Integer target = configManager.getRSProfileConfiguration(PROFILE_GROUP, "goal-" + key, int.class);
		Integer celebrated = configManager.getRSProfileConfiguration(PROFILE_GROUP, "goal-celebrated-" + key, int.class);
		Integer goalCount = config.personalGoalBasis().count(sinceEnabled, sessionKills.getOrDefault(key, 0), total);
		boolean lifetimeGoal = config.personalGoalBasis() == BossKillMilestonesConfig.MilestoneBasis.ALL_TIME;
		// Local counters advance by one per recorded kill. Crossing the target avoids
		// replaying a goal after changing basis and lets session goals repeat after logout.
		boolean goalReached = lifetimeGoal ? Celebration.goalReached(target == null ? 0 : target, goalCount, celebrated)
			: target != null && target > 0 && target.equals(goalCount);
		if (goalReached && lifetimeGoal) configManager.setRSProfileConfiguration(PROFILE_GROUP, "goal-celebrated-" + key, target);
		Integer milestoneCount = config.milestoneBasis().count(sinceEnabled, sessionKills.getOrDefault(key, 0), total);
		Celebration celebration = Celebration.select(milestoneCount == null ? 0 : milestoneCount, sessionKills.getOrDefault(key, 0),
			config.sessionCelebrations().interval, goalReached);
		if (celebration != null)
		{
			if (config.milestoneFireworks())
			{
				fireworksOverlay.launch(celebration);
			}
			String introduction = celebration == Celebration.GOAL ? "Personal goal reached: " + target + " " + bossName + " (" + config.personalGoalBasis() + ")! "
				: celebration == Celebration.SESSION ? "Session milestone: " + sessionKills.get(key) + " " + bossName + " this session! "
				: celebration == Celebration.THOUSAND || celebration == Celebration.TWO_FIFTY ? celebration.title + "! " : "";
			String countMessage = config.milestoneBasis() == BossKillMilestonesConfig.MilestoneBasis.ALL_TIME
				? "You've reached " + (total == null ? "an unknown number of" : total) + " " + bossName + (estimated ? " estimated all-time kills!" : " all-time kills!")
				: config.milestoneBasis() == BossKillMilestonesConfig.MilestoneBasis.SESSION
				? "You've killed " + sessionKills.get(key) + " " + bossName + " this session!"
				: "You've killed " + sinceEnabled + " " + bossName + " since Boss Milestones: Rank Among Friends was enabled!";
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", introduction + countMessage + (total == null ? " (lifetime total unconfirmed)"
				: " (" + total + (estimated ? " estimated total)" : " total)")), null);
			if (config.playMilestoneSound())
			{
				milestoneAudio.play(celebration, config.soundVolume());
			}
		}
	}

	private boolean isExcluded(String bossName)
	{
		String normalizedBoss = BossNames.normalize(bossName);
		for (String excluded : config.excludedBosses().split(","))
		{
			String known = BossNames.known(excluded);
			if (normalizedBoss.equals(BossNames.normalize(known == null ? excluded : known)))
			{
				return true;
			}
		}
		return false;
	}

	static boolean isBossKillCountMessage(String boss, String prefix, String suffix)
	{
		// Barrows reports "Your Barrows chest count is", not a kill count.
		// Restrict this exception to Barrows rather than accepting arbitrary counts.
		if ("Barrows Chests".equals(BossNames.known(Text.removeTags(boss))) && "count ".equals(suffix))
		{
			return true;
		}
		return (suffix != null && (suffix.contains("kill count")
			|| suffix.contains("completion count")
			|| suffix.contains("success count")))
			|| (prefix != null && (prefix.startsWith("subdued ") || prefix.startsWith("completed ")
			|| prefix.startsWith("completion count for ")));
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!ready() || event.getComposition() == null)
		{
			return;
		}
		boolean testGuard = config.testGuard() && client.getLocalPlayer() != null
			&& TestGuard.matches(event.getComposition().getName(), event.getComposition().getCombatLevel(), client.getLocalPlayer().getWorldLocation());
		if (!testGuard && !config.lootBackup()) return;
		String boss = testGuard ? TestGuard.NAME : BossNames.known(event.getComposition().getName());
		if (boss == null || isExcluded(boss))
		{
			return;
		}
		String key = BossNames.key(boss);
		int tick = client.getTickCount();
		Integer previous = lastLootTicks.put(key, tick);
		if (previous != null && previous == tick)
		{
			return;
		}
		if (signals.accept(key, true, tick))
		{
			Integer estimate = configManager.getRSProfileConfiguration(PROFILE_GROUP, "estimated-total-" + key, int.class);
			if (estimate == null)
			{
				estimate = configManager.getRSProfileConfiguration(PROFILE_GROUP, "total-" + key, int.class);
			}
			if (estimate != null)
			{
				estimate++;
				configManager.setRSProfileConfiguration(PROFILE_GROUP, "estimated-total-" + key, estimate);
			}
			recordKill(boss, estimate, true);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			clearSession();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			resetTransientState();
		}
		sidebar.update();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PROFILE_GROUP.equals(event.getGroup()))
		{
			if ("syncDiagnostics".equals(event.getKey())) lastPanel = null;
			sidebar.requestUpdate();
		}
	}

	private void resetTransientState()
	{
		signals.clear();
		lastLootTicks.clear();
		reminded = false;
		lastPanel = null;
	}

	private boolean ready()
	{
		if (client.getGameState() != GameState.LOGGED_IN || configManager.getRSProfileKey() == null)
		{
			return false;
		}
		String current = configManager.getRSProfileKey();
		if (!Objects.equals(profile, current))
		{
			clearSession();
			resetTransientState();
			profile = current;
			migrateNames();
			// Seed existing completed goals without replaying them after an upgrade/login.
			for (String boss : BossNames.all()) acknowledgeCompletedGoal(boss);
		}
		return true;
	}

	private void migrateNames()
	{
		// Preserve records written before aliases were canonicalised.
		String[] aliases = {"The Nightmare", "Barrows chest", "Gauntlet", "Corrupted Gauntlet", "Hueycoatl", "Royal Titans", "Leviathan", "Whisperer"};
		for (String alias : aliases)
		{
			String canonical = BossNames.known(alias);
			if (canonical == null || BossNames.key(alias).equals(BossNames.key(canonical)))
			{
				continue;
			}
			for (String prefix : new String[]{"since-enabled-", "total-"})
			{
				String target = prefix + BossNames.key(canonical);
				Integer old = configManager.getRSProfileConfiguration(PROFILE_GROUP, prefix + BossNames.key(alias), int.class);
				if (old != null && configManager.getRSProfileConfiguration(PROFILE_GROUP, target, int.class) == null)
				{
					configManager.setRSProfileConfiguration(PROFILE_GROUP, target, old);
				}
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ready())
		{
			return;
		}
		if (!reminded)
		{
			reminded = true;
			Boolean synced = configManager.getRSProfileConfiguration(PROFILE_GROUP, "initial-sync", boolean.class);
			if (config.syncReminder() && !Boolean.TRUE.equals(synced))
			{
				message("To sync lifetime totals, open a boss's Combat Achievements details showing its kill count. Each boss is saved separately and refreshed whenever you revisit it.");
			}
		}
		syncCombatAchievements();
		refreshProgress();
		sidebar.update();
	}

	private void syncCombatAchievements()
	{
		Widget title = client.getWidget(InterfaceID.CaBoss.BOSS_NAME);
		Widget stats = client.getWidget(InterfaceID.CaBoss.CA_BOSS_STATS);
		if (title == null || stats == null || title.isHidden() || stats.isHidden())
		{
			lastPanel = null;
			return;
		}
		StringBuilder titleText = new StringBuilder();
		appendText(title, titleText);
		String boss = BossNames.known(Text.removeTags(titleText.toString()).trim());
		StringBuilder text = new StringBuilder();
		appendText(stats, text);
		String fingerprint = boss + "\n" + text;
		if (fingerprint.equals(lastPanel))
		{
			return;
		}
		lastPanel = fingerprint;
		Integer total = BossStats.parse(text.toString());
		if (boss == null || total == null)
		{
			log.debug("Lifetime sync skipped: boss title={}, statistics={}", titleText, text);
			if (config.syncDiagnostics())
			{
				String observed = Text.removeTags(text.toString().replace("<br>", " | ")).replace('\n', ' ');
				message("Could not sync " + Text.removeTags(titleText.toString()).trim()
					+ ". Visible stats: " + observed.substring(0, Math.min(300, observed.length())));
			}
			return;
		}
		// Sync is a snapshot, never a kill event: do not modify milestone progress.
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "total-" + BossNames.key(boss), total);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "estimated-total-" + BossNames.key(boss), total);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "last-chat-" + BossNames.key(boss), total);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "initial-sync", true);
		acknowledgeCompletedGoal(boss);
		activeBoss = boss;
		refreshProgress();
		message("Synced " + boss + ": " + total + " lifetime kills. Your milestone progress is unchanged.");
	}

	private static void appendText(Widget widget, StringBuilder output)
	{
		appendText(widget, output, java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>()));
	}

	private static void appendText(Widget widget, StringBuilder output, java.util.Set<Widget> visited)
	{
		if (widget == null || !visited.add(widget) || widget.isHidden())
		{
			return;
		}
		String value = widget.getText();
		if (value != null && !value.isEmpty())
		{
			output.append(value).append('\n');
		}
		// getChildren() covers only dynamic children; do not omit static/nested text.
		for (Widget[] children : new Widget[][]{widget.getChildren(), widget.getStaticChildren(), widget.getNestedChildren()})
		{
			if (children == null) continue;
			for (Widget child : children)
			{
				if (child != null)
				{
					appendText(child, output, visited);
				}
			}
		}
	}

	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Boss Milestones: Rank Among Friends: " + text, null);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (!ready() || event.getSource() != client.getLocalPlayer() || !(event.getTarget() instanceof NPC)) return;
		NPC npc = (NPC) event.getTarget();
		String boss = config.testGuard() && TestGuard.matches(npc.getName(), npc.getCombatLevel(), npc.getWorldLocation())
			? TestGuard.NAME : BossNames.known(npc.getName());
		if (boss != null && !isExcluded(boss))
		{
			activeBoss = boss;
			refreshProgress();
		}
	}

	private void clearSession()
	{
		overlayActivity.reset();
		sessionKills.clear();
		activeBoss = null;
		progress = new Progress("Waiting for a target", 0, 0, "Unknown");
	}

	private void refreshProgress()
	{
		if (activeBoss == null) return;
		if (isExcluded(activeBoss) || (TestGuard.NAME.equals(activeBoss) && !config.testGuard()))
		{
			activeBoss = null;
			progress = new Progress("Waiting for a target", 0, 0, "Unknown");
			return;
		}
		progress = progressFor(activeBoss);
	}

	String getActiveBoss()
	{
		return activeBoss;
	}

	Progress progressFor(String boss)
	{
		if (boss == null) return new Progress("Choose a boss", 0, 0, "Unknown");
		String key = BossNames.key(boss);
		Integer saved = configManager.getRSProfileConfiguration(PROFILE_GROUP, "since-enabled-" + key, int.class);
		Integer total = configManager.getRSProfileConfiguration(PROFILE_GROUP, "total-" + key, int.class);
		Integer estimate = configManager.getRSProfileConfiguration(PROFILE_GROUP, "estimated-total-" + key, int.class);
		String totalText = total == null ? "Unknown" : total.toString();
		if (estimate != null && !estimate.equals(total)) totalText = "~" + estimate;
		Integer goal = configManager.getRSProfileConfiguration(PROFILE_GROUP, "goal-" + key, int.class);
		return new Progress(boss, sessionKills.getOrDefault(key, 0), saved == null ? 0 : saved, totalText, goal == null ? 0 : goal, config.milestoneBasis(), config.personalGoalBasis());
	}

	void saveGoal(String boss, int goal)
	{
		if (!ready() || !BossNames.all().contains(boss) || goal < 0) return;
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "goal-" + BossNames.key(boss), goal);
		configManager.setRSProfileConfiguration(PROFILE_GROUP, "goal-celebrated-" + BossNames.key(boss), 0);
		acknowledgeCompletedGoal(boss);
		refreshProgress();
	}

	private void acknowledgeCompletedGoal(String boss)
	{
		String key = BossNames.key(boss);
		Integer target = configManager.getRSProfileConfiguration(PROFILE_GROUP, "goal-" + key, int.class);
		Integer total = GrindProgress.total(progressFor(boss).total);
		if (target != null && target > 0 && total != null && total >= target)
			configManager.setRSProfileConfiguration(PROFILE_GROUP, "goal-celebrated-" + key, target);
	}

	String rivalFor(String boss)
	{
		return sidebar.rivalFor(boss);
	}

	@Provides
	BossKillMilestonesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossKillMilestonesConfig.class);
	}
}

package com.bosskillmilestones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

final class BossMilestoneOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(240, 187, 88);
	private static final Color MUTED = new Color(184, 173, 157);
	private static final Color EDGE = new Color(158, 111, 46, 220);
	private static final Color GOAL = new Color(90, 200, 180);
	private final Client client;
	private final BossKillMilestonesPlugin plugin;
	private final BossKillMilestonesConfig config;

	@Inject
	BossMilestoneOverlay(Client client, BossKillMilestonesPlugin plugin, BossKillMilestonesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setResizable(false);
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(260, 0));
		panelComponent.setBackgroundColor(new Color(23, 15, 20, 235));
		panelComponent.setBorder(new java.awt.Rectangle(10, 10, 10, 10));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay() || client.getGameState() != GameState.LOGGED_IN || !plugin.isCounterVisible()) return null;
		BossKillMilestonesPlugin.Progress progress = plugin.getProgress();
		BossKillMilestonesConfig.OverlayLayout layout = config.overlayLayout();
		int width = layout == BossKillMilestonesConfig.OverlayLayout.FULL ? 260
			: layout == BossKillMilestonesConfig.OverlayLayout.COMPACT ? 210 : 175;
		panelComponent.setPreferredSize(new Dimension(width, 0));
		setPreferredSize(new Dimension(width, 0));
		panelComponent.setBorder(new java.awt.Rectangle(7, 7, 7, 7));
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text(progress.name).color(GOLD).build());
		add("This session", Integer.toString(progress.session));
		add("Since enabled", Integer.toString(progress.saved));
		if (layout == BossKillMilestonesConfig.OverlayLayout.MINIMAL)
		{
			add("Next milestone", progress.nextMilestoneText());
			add("Personal goal", progress.goal <= 0 ? "Not set"
				: progress.goalCount() == null ? "Sync total"
				: progress.goalCount() >= progress.goal ? "Reached!"
				: progress.goalCountText() + " / " + progress.goal);
			return renderThemedPanel(graphics);
		}
		add("Total", progress.total);
		if (layout == BossKillMilestonesConfig.OverlayLayout.COMPACT)
		{
			add("Next milestone", progress.nextMilestoneText());
			Integer lifetime = progress.goalCount();
			if (progress.goal > 0)
			{
				add("Personal goal", lifetime == null ? "Sync total" : lifetime >= progress.goal ? "Reached!" : (progress.goal - lifetime) + " away");
				bar(lifetime == null ? 0 : lifetime, progress.goal, progress.goalCountText() + " / " + progress.goal, GOAL);
			}
			else add("Personal goal", "Set in sidebar");
			return renderThemedPanel(graphics);
		}
		if (config.showGrindGoals())
		{
			Integer count = progress.milestoneCount();
			add("NEXT JINGLE", progress.nextMilestoneText());
			add("Based on", progress.basis.toString());
			if (count != null)
			{
				long next = GrindProgress.nextMilestone(count);
				bar(count, next, count + " / " + next, GOLD);
			}
			Integer total = progress.goalCount();
			if (progress.goal > 0)
			{
				add("PERSONAL GOAL", total == null ? "Sync lifetime total" : total >= progress.goal ? "Reached!" : (progress.goal - total) + " to go");
				add("Goal basis", progress.goalBasis.toString());
				bar(total == null ? 0 : total, progress.goal, progress.goalCountText() + " / " + progress.goal, GOAL);
			}
			else add("Personal goal", "Set in sidebar");
			add("FRIEND TO BEAT", "Cached hiscores");
			panelComponent.getChildren().add(LineComponent.builder().left(plugin.rivalFor(progress.name))
				.leftColor(new Color(130, 210, 255)).build());
		}
		return renderThemedPanel(graphics);
	}

	private Dimension renderThemedPanel(Graphics2D graphics)
	{
		Dimension size = super.render(graphics);
		if (size != null && size.width > 0 && size.height > 0)
		{
			Graphics2D frame = (Graphics2D) graphics.create();
			try
			{
				frame.setColor(EDGE);
				frame.drawRect(0, 0, size.width - 1, size.height - 1);
				frame.setColor(GOLD);
				frame.drawLine(7, 0, size.width - 8, 0);
			}
			finally { frame.dispose(); }
		}
		return size;
	}

	private void bar(long value, long maximum, String label, Color color)
	{
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMaximum(maximum);
		bar.setValue(Math.min(value, maximum));
		bar.setForegroundColor(color);
		bar.setBackgroundColor(new Color(47, 27, 33));
		bar.setCenterLabel(label);
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
		panelComponent.getChildren().add(bar);
	}

	private void add(String label, String value)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(label).leftColor(MUTED)
			.right(value).rightColor(GOLD).build());
	}
}

package com.bosskillmilestones;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class BossNames
{
	private static final Map<String, String> NAMES = new HashMap<>();
	static
	{
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() == HiscoreSkillType.BOSS)
			{
				NAMES.put(normalize(skill.getName()), skill.getName());
				if (skill.getName().startsWith("The "))
				{
					NAMES.put(normalize(skill.getName().substring(4)), skill.getName());
				}
			}
		}
		alias("The Nightmare", "Nightmare");
		alias("Dusk", "Grotesque Guardians");
		alias("Barrows chest", "Barrows Chests");
		alias("Barrows", "Barrows Chests");
		alias("Lunar chest", "Lunar Chests");
		alias("Theatre of Blood Entry Mode", "Theatre of Blood: Entry Mode");
		alias("Tombs of Amascut Entry Mode", "Tombs of Amascut: Entry Mode");
	}

	private static void alias(String alias, String name)
	{
		NAMES.put(normalize(alias), name);
	}

	static String known(String name)
	{
		return name == null ? null : NAMES.get(normalize(name));
	}

	static java.util.List<String> all()
	{
		java.util.TreeSet<String> names = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		names.addAll(NAMES.values());
		names.add(TestGuard.NAME);
		return new java.util.ArrayList<>(names);
	}

	static HiscoreSkill hiscore(String name)
	{
		if (name == null) return null;
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() == HiscoreSkillType.BOSS && normalize(skill.getName()).equals(normalize(name))) return skill;
		}
		return null;
	}

	static String normalize(String name)
	{
		return name.replace(':', ' ').replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
	}

	static String key(String name)
	{
		return normalize(name).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
	}
}

package com.bosskillmilestones;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Nameable;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Singleton
final class BossSidebar
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar toolbar;
	@Inject private SpriteManager sprites;
	@Inject private ConfigManager configManager;
	@Inject private BossKillMilestonesConfig config;
	@Inject private BossKillMilestonesPlugin plugin;
	@Inject private FriendLeaderboard leaderboard;
	private final AtomicLong lifecycle = new AtomicLong();
	private final AtomicLong boardVersion = new AtomicLong();
	private volatile BossSidebarPanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	// The following state is owned by the client thread.
	private boolean active;
	private String selected;
	private volatile String profile;
	private String context;
	private String pictured;
	private final java.util.Map<String, String> rivals = new java.util.concurrent.ConcurrentHashMap<>();

	String rivalFor(String boss)
	{
		return config.friendHiscores() ? rivals.getOrDefault(boss, "Open sidebar to load friends") : "Enable friends hiscores to compare";
	}

	void start()
	{
		running = true;
		long life = lifecycle.incrementAndGet();
		leaderboard.start();
		SwingUtilities.invokeLater(() -> {
			if (!running || life != lifecycle.get()) return;
			if (navigation != null) toolbar.removeNavigation(navigation);
			panel = new BossSidebarPanel(boss -> clientThread.invokeLater(() -> {
				selected = boss; context = null; update();
			}), () -> clientThread.invokeLater(() -> { context = null; update(); }),
				() -> clientThread.invokeLater(() -> { active = true; context = null; update(); }),
				() -> clientThread.invokeLater(() -> {
					active = false; context = null; boardVersion.incrementAndGet(); leaderboard.cancel();
				}), (boss, goal) -> {
				String account = profile;
				clientThread.invokeLater(() -> {
					if (Objects.equals(account, configManager.getRSProfileKey())) { plugin.saveGoal(boss, goal); update(); }
				});
			});
			navigation = NavigationButton.builder().tooltip("Boss Milestones: Rank Among Friends")
				.icon(BossSidebarPanel.icon(24)).priority(7).panel(panel).build();
			toolbar.addNavigation(navigation);
			clientThread.invokeLater(() -> {
				if (life != lifecycle.get()) return;
				active = false; selected = null; profile = null; context = null; pictured = null; update();
			});
		});
	}

	void stop()
	{
		running = false;
		long life = lifecycle.incrementAndGet();
		boardVersion.incrementAndGet();
		leaderboard.stop();
		rivals.clear();
		SwingUtilities.invokeLater(() -> {
			if (life != lifecycle.get()) return;
			if (navigation != null) toolbar.removeNavigation(navigation);
			navigation = null; panel = null;
		});
	}

	void requestUpdate()
	{
		clientThread.invokeLater(this::update);
	}

	void update()
	{
		BossSidebarPanel target = panel;
		if (!running || target == null) return;
		// Region loading is not a logout: player/profile data may briefly be absent.
		if (preserveDuringTransition(client.getGameState(), profile, configManager.getRSProfileKey()))
		{
			if (!config.friendHiscores())
			{
				boardVersion.incrementAndGet(); leaderboard.cancel(); context = null;
				ui(target, () -> target.message("Enable Friends hiscore leaderboard in the plugin settings."));
			}
			return;
		}
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN
			&& configManager.getRSProfileKey() != null && client.getLocalPlayer() != null;
		String account = loggedIn ? configManager.getRSProfileKey() : null;
		if (!Objects.equals(profile, account))
		{
			profile = account; context = null; pictured = null;
			boardVersion.incrementAndGet(); leaderboard.clear();
			rivals.clear();
		}
		String boss = loggedIn ? (selected == null ? plugin.getActiveBoss() : selected) : null;
		BossKillMilestonesPlugin.Progress progress = loggedIn ? plugin.progressFor(boss)
			: new BossKillMilestonesPlugin.Progress("Log in to view kills", 0, 0, "Unknown");
		ui(target, () -> target.showProgress(progress));
		ui(target, () -> target.showRival(boss == null ? "Choose a boss" : rivalFor(boss)));
		HiscoreSkill skill = BossNames.hiscore(boss);
		if (!Objects.equals(pictured, boss))
		{
			pictured = boss;
			if (skill != null && skill.getSpriteId() >= 0)
			{
				sprites.getSpriteAsync(skill.getSpriteId(), 0, image -> ui(target, () -> target.showImage(boss, image)));
			}
		}
		String message = !loggedIn ? "Log in to view your account's friends."
			: !config.friendHiscores() ? "Enable Friends hiscore leaderboard in the plugin settings."
			: skill == null ? "Choose a boss with public hiscores. No hiscores are available for the test guard or entry modes."
			: !active ? "Open this panel to load friends." : null;
		List<String> names = new ArrayList<>();
		String own = loggedIn ? client.getLocalPlayer().getName() : null;
		if (message == null)
		{
			if (client.getFriendContainer() != null)
				for (Nameable friend : client.getFriendContainer().getMembers()) names.add(friend.getName());
			names.sort(String.CASE_INSENSITIVE_ORDER);
			names.add(0, own);
		}
		List<String> roster = FriendLeaderboard.uniqueNames(names);
		String nextContext = account + "|" + boss + "|" + message + "|" + roster;
		if (nextContext.equals(context)) return;
		context = nextContext;
		long version = boardVersion.incrementAndGet();
		leaderboard.cancel();
		if (message != null)
		{
			ui(target, () -> { if (version == boardVersion.get()) target.message(message); });
			return;
		}
		leaderboard.refresh(roster, skill, view -> ui(target, () -> {
			if (version == boardVersion.get())
			{
				String rival = GrindProgress.rival(view, own);
				rivals.put(boss, rival);
				target.showRival(rival);
				target.showBoard(view, own);
			}
		}));
	}

	static boolean preserveDuringTransition(GameState state, String previousProfile, String currentProfile)
	{
		return previousProfile != null && (currentProfile == null || previousProfile.equals(currentProfile))
			&& (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.CONNECTION_LOST);
	}

	private void ui(BossSidebarPanel target, Runnable action)
	{
		long life = lifecycle.get();
		SwingUtilities.invokeLater(() -> {
			if (running && life == lifecycle.get() && panel == target) action.run();
		});
	}
}

