	boolean showProgress(BossKillMilestonesPlugin.Progress progress)
	{
		boolean changed = !Objects.equals(shownBoss, progress.name);
		if (changed || shownGoal != progress.goal)
		{
			shownGoal = progress.goal;
			goalInput.setValue(progress.goal);
		}
		Integer count = progress.milestoneCount();
		long next = GrindProgress.nextMilestone(count == null ? 0 : count);
		milestone.setValue(count == null ? 0 : (int) (100.0 * count / next));
		milestone.setString(count == null ? "Sync lifetime total" : "Next jingle: " + count + " / " + next);
		milestone.setToolTipText("Milestone basis: " + progress.basis);
		Integer lifetime = progress.goalCount();
		personal.setToolTipText("Personal goal basis: " + progress.goalBasis);
		goalInput.setToolTipText("Target based on " + progress.goalBasis + "; 0 clears the goal.");
		personal.setValue(progress.goal > 0 && lifetime != null ? (int) Math.min(100, 100.0 * lifetime / progress.goal) : 0);
		personal.setString(progress.goal <= 0 ? "Set a goal below" : lifetime == null ? "Goal " + progress.goal + " — sync total"
			: lifetime >= progress.goal ? "Goal reached! " + progress.goal : "Goal: " + progress.goalCountText() + " / " + progress.goal);
		shownBoss = progress.name;
		title.setText(progress.name);
		title.setToolTipText(progress.name);
		total.setText(progress.total);
		saved.setText(Integer.toString(progress.saved));
		session.setText(Integer.toString(progress.session));
		if (changed) image.setIcon(new ImageIcon(icon(96)));
		return changed;
	}

	void showImage(String boss, BufferedImage sprite)
	{
		if (!Objects.equals(shownBoss, boss)) return;
		BufferedImage enlarged = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = enlarged.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		double scale = Math.min(96.0 / sprite.getWidth(), 96.0 / sprite.getHeight());
		int width = (int) (sprite.getWidth() * scale), height = (int) (sprite.getHeight() * scale);
		graphics.drawImage(sprite, (96 - width) / 2, (96 - height) / 2, width, height, null);
		graphics.dispose();
		image.setIcon(new ImageIcon(enlarged));
	}

	void showRival(String text)
	{
		rival.setText(text);
		rival.setToolTipText("Cached public hiscores: " + text);
	}

	private static JProgressBar progressBar(Color color)
	{
		JProgressBar bar = new JProgressBar(0, 100);
		bar.setStringPainted(true);
		bar.setForeground(color);
		bar.setBackground(SURFACE);
		bar.setBorder(BorderFactory.createLineBorder(EDGE));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		return bar;
	}

	void showBoard(FriendLeaderboard.View view, String ownName)
	{
		table.setRowCount(0);
		hasOwnSummary = false;
		int rank = 0;
		for (FriendLeaderboard.Row row : view.rows)
		{
			table.addRow(new Object[]{row.kills == null ? "—" : Integer.toString(++rank),
				row.name + (row.name.equalsIgnoreCase(ownName) ? " (you)" : ""),
				row.kills == null ? row.status : String.format("%,d", row.kills)});
			if (row.name.replace('\u00a0', ' ').trim().equalsIgnoreCase(ownName == null ? "" : ownName.replace('\u00a0', ' ').trim()))
			{
				hasOwnSummary = true;
				// Copy this exact rank; the summary must not affect the ordered ranks.
				Object[] summary = {row.kills == null ? "—" : Integer.toString(rank), row.name + " (you)",
					row.kills == null ? row.status : String.format("%,d", row.kills)};
				table.insertRow(0, summary);
			}
		}
		status.setText(view.status);
	}

	void message(String text)
	{
		hasOwnSummary = false;
		table.setRowCount(0);
		status.setText(text);
	}

	@Override public void onActivate() { activate.run(); }
	@Override public void onDeactivate() { deactivate.run(); }

	static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.drawImage(ICON, 0, 0, size, size, null);
		g.dispose();
		return image;
	}
}

package com.bosskillmilestones;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

final class BossStats
{
	private static final Pattern COUNT = Pattern.compile(
		"(?im)(?:^|\\n)[ \\t]*(?:kill\\s*count|kills|completion count|completions|success count|subdued)[ \\t]*:?[ \\t]*(?:\\n[ \\t]*)?([0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)[ \\t]*(?=$|\\n)");

	/** Only accept explicit totals; achievement progress and times are not kill counts. */
	static Integer parse(String text)
	{
		if (text == null) return null;
		String plain = Text.removeTags(text.replaceAll("(?i)<br\\s*/?>", "\n"))
			.replace('\u00a0', ' ').replace("\r\n", "\n");
		Matcher matcher = COUNT.matcher(plain);
		if (!matcher.find())
		{
			return null;
		}
		try
		{
			int count = Integer.parseInt(matcher.group(1).replace(",", ""));
			return matcher.find() ? null : count;
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.bosskillmilestones;

enum Celebration
{
	SESSION("session-spark", "Session milestone"),
	TEN("little-victory", "First ten"),
	TWENTY_FIVE("golden-steps", "First twenty-five"),
	FIFTY("little-victory", "Milestone"),
	TWO_FIFTY("champion-fanfare", "250-kill milestone"),
	THOUSAND("legendary-victory", "1,000-kill milestone"),
	GOAL("goal-complete", "Personal goal reached");

	final String resource;
	final String title;
	Celebration(String resource, String title)
	{
		this.resource = "/audio/" + resource + ".wav";
		this.title = title;
	}

	static Celebration select(int saved, int session, int sessionInterval, boolean goalReached)
	{
		if (goalReached) return GOAL;
		if (saved > 0 && saved % 1000 == 0) return THOUSAND;
		if (saved > 0 && saved % 250 == 0) return TWO_FIFTY;
		if (saved > 0 && saved % 50 == 0) return FIFTY;
		if (saved == 25) return TWENTY_FIVE;
		if (saved == 10) return TEN;
		if ((sessionInterval == 10 || sessionInterval == 25) && session > 0 && session % sessionInterval == 0) return SESSION;
		return null;
	}

	static boolean goalReached(int target, Integer total, Integer celebrated)
	{
		return target > 0 && total != null && total >= target && !Integer.valueOf(target).equals(celebrated);
	}
}

package com.bosskillmilestones;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
final class FireworksOverlay extends Overlay
{
	private static final long DISPLAY_NANOS = 3_400_000_000L;
	private static final Color[] COLORS = {
		new Color(255, 205, 85), new Color(255, 93, 72), new Color(115, 220, 255),
		new Color(255, 125, 210), new Color(175, 255, 125), new Color(205, 155, 255)
	};

	private final Client client;
	private final List<Spark> sparks = new ArrayList<>();

	@Inject
	FireworksOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	synchronized void launch(Celebration celebration)
	{
		int width = client.getCanvasWidth();
		int height = client.getCanvasHeight();
		if (width <= 0 || height <= 0)
		{
			return;
		}

		int bursts = burstCount(celebration);
		long now = System.nanoTime();
		ThreadLocalRandom random = ThreadLocalRandom.current();
		for (int burst = 0; burst < bursts; burst++)
		{
			// Spread the bursts across the visible scene and vary their height.
			double sceneFraction = (burst + 0.5) / bursts;
			int centerX = (int) (width * (0.12 + 0.76 * sceneFraction))
				+ random.nextInt(-Math.max(1, width / 24), Math.max(2, width / 24));
			int centerY = (int) (height * random.nextDouble(0.18, 0.52));
			int count = sparksPerBurst(celebration);
			for (int i = 0; i < count; i++)
			{
				double angle = Math.PI * 2 * i / count + random.nextDouble(-0.045, 0.045);
				double speed = random.nextDouble(35, 100);
				long delay = burst * 140_000_000L;
				sparks.add(new Spark(centerX, centerY, Math.cos(angle) * speed,
					Math.sin(angle) * speed, now + delay, random.nextInt(3, 6), COLORS[random.nextInt(COLORS.length)]));
			}
		}
		// Guard against a rapid sequence of milestones retaining too many particles.
		if (sparks.size() > 1600)
		{
			sparks.subList(0, sparks.size() - 1600).clear();
		}
	}

	static int burstCount(Celebration celebration)
	{
		switch (celebration)
		{
			case TEN:
		case SESSION:
			return 2;
			case TWENTY_FIVE:
			return 3;
			case FIFTY:
			return 5;
			case GOAL:
		case TWO_FIFTY:
			return 8;
			case THOUSAND:
			return 12;
			default:
			return 1;
		}
	}

	private static int sparksPerBurst(Celebration celebration)
	{
		switch (celebration)
		{
			case TEN:
		case SESSION:
			return 18;
			case TWENTY_FIVE:
			return 24;
			case FIFTY:
			return 28;
			case GOAL:
		case TWO_FIFTY:
			return 34;
			case THOUSAND:
			return 42;
			default:
			return 16;
		}
	}

	@Override
	public synchronized Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			sparks.clear();
			return null;
		}

		long now = System.nanoTime();
		Iterator<Spark> iterator = sparks.iterator();
		while (iterator.hasNext())
		{
			Spark spark = iterator.next();
			long ageNanos = now - spark.started;
			if (ageNanos < 0)
			{
				continue;
			}
			if (ageNanos >= DISPLAY_NANOS)
			{
				iterator.remove();
				continue;
			}

			double seconds = ageNanos / 1_000_000_000.0;
			double x = spark.x + spark.velocityX * seconds;
			double y = spark.y + spark.velocityY * seconds + 24 * seconds * seconds;
			float fade = (float) (1.0 - seconds / (DISPLAY_NANOS / 1_000_000_000.0));
			int alpha = Math.max(0, Math.min(255, (int) (fade * 255)));
			Color color = new Color(spark.color.getRed(), spark.color.getGreen(), spark.color.getBlue(), alpha);
			graphics.setColor(color);
			graphics.fillOval((int) x - spark.size / 2, (int) y - spark.size / 2, spark.size, spark.size);
			if (spark.size >= 4)
			{
				graphics.setColor(new Color(255, 255, 235, alpha));
				graphics.fillOval((int) x - 1, (int) y - 1, 2, 2);
			}
		}
		return null;
	}

	private static final class Spark
	{
		private final int x;
		private final int y;
		private final double velocityX;
		private final double velocityY;
		private final long started;
		private final int size;
		private final Color color;

		private Spark(int x, int y, double velocityX, double velocityY, long started, int size, Color color)
		{
			this.x = x;
			this.y = y;
			this.velocityX = velocityX;
			this.velocityY = velocityY;
			this.started = started;
			this.size = size;
			this.color = color;
		}
	}
}

package com.bosskillmilestones;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;

@Singleton
final class FriendLeaderboard
{
	static final class Row
	{
		final String name;
		final Integer kills;
		final String status;
		Row(String name, Integer kills, String status)
		{
			this.name = name;
			this.kills = kills;
			this.status = status;
		}
	}

	static final class View
	{
		final List<Row> rows;
		final String status;
		View(List<Row> rows, String status)
		{
			this.rows = Collections.unmodifiableList(sorted(rows));
			this.status = status;
		}
	}

	private static final class Cached
	{
		final HiscoreResult result;
		final boolean failed;
		final long expires;
		Cached(HiscoreResult result, boolean failed)
		{
			this.result = result;
			this.failed = failed;
			this.expires = System.nanoTime() + TimeUnit.MINUTES.toNanos(failed ? 1 : 10);
		}
	}

	private final HiscoreClient hiscores;
	private final Map<String, Cached> cache = new LinkedHashMap<>();
	private ScheduledExecutorService worker;
	private ScheduledFuture<?> pending;
	private long generation;
	private long nextLookup;

	@Inject
	FriendLeaderboard(HiscoreClient hiscores)
	{
		this.hiscores = hiscores;
	}

	synchronized void start()
	{
		stop();
		worker = Executors.newSingleThreadScheduledExecutor(task -> {
			Thread thread = new Thread(task, "boss-friends-hiscores");
			thread.setDaemon(true);
			return thread;
		});
	}

	synchronized void cancel()
	{
		generation++;
		if (pending != null) pending.cancel(true);
		pending = null;
	}

	synchronized void clear()
	{
		cancel();
		cache.clear();
	}

	synchronized void stop()
	{
		clear();
		if (worker != null) worker.shutdownNow();
		worker = null;
	}

	synchronized void refresh(List<String> names, HiscoreSkill boss, Consumer<View> consumer)
	{
		cancel();
		if (worker == null) return;
		List<String> roster = uniqueNames(names);
		List<Row> rows = new ArrayList<>();
		for (String name : roster) rows.add(new Row(name, null, "Waiting"));
		consumer.accept(new View(rows, "Loading 0 / " + roster.size()));
		long request = generation;
		pending = worker.schedule(() -> next(request, roster, rows, boss, consumer, 0, 0), 0, TimeUnit.MILLISECONDS);
	}

	private void next(long request, List<String> names, List<Row> rows, HiscoreSkill boss,
		Consumer<View> consumer, int index, int failures)
	{
		if (index >= names.size()) return;
		String name = names.get(index);
		String key = name.toLowerCase(Locale.ROOT);
		Cached entry;
		synchronized (this)
		{
			if (request != generation || worker == null) return;
			entry = cache.get(key);
			if (entry == null || System.nanoTime() - entry.expires >= 0)
			{
				long delay = nextLookup - System.nanoTime();
				if (delay > 0)
				{
					pending = worker.schedule(() -> next(request, names, rows, boss, consumer, index, failures), delay, TimeUnit.NANOSECONDS);
					return;
				}
				nextLookup = System.nanoTime() + TimeUnit.SECONDS.toNanos(1);
			}
		}
		boolean fetched = entry == null || System.nanoTime() - entry.expires >= 0;
		if (fetched)
		{
			try { entry = new Cached(hiscores.lookup(name), false); }
			catch (Exception ex) { entry = new Cached(null, true); }
		}
		synchronized (this)
		{
			if (request != generation || worker == null) return;
			if (fetched)
			{
				if (cache.size() >= 500) cache.remove(cache.keySet().iterator().next());
				cache.put(key, entry);
			}
			rows.set(index, row(name, entry.result, boss, entry.failed));
			int errors = entry.failed ? failures + 1 : 0;
			boolean finished = index + 1 == names.size();
			String status = finished ? "Updated — cached up to 10 min" : "Loading " + (index + 1) + " / " + names.size();
			if (errors >= 3 && !finished) status = "Service unavailable — refresh later";
			consumer.accept(new View(rows, status));
			if (!finished && errors < 3)
			{
				pending = worker.schedule(() -> next(request, names, rows, boss, consumer, index + 1, errors),
					fetched ? 1000 : 0, TimeUnit.MILLISECONDS);
			}
		}
	}

	static Row row(String name, HiscoreResult result, HiscoreSkill boss, boolean failed)
	{
		if (failed) return new Row(name, null, "Unavailable");
		Skill skill = result == null ? null : result.getSkill(boss);
		if (skill == null || skill.getRank() < 0 || skill.getLevel() < 0) return new Row(name, null, "Unranked");
		return new Row(name, skill.getLevel(), "");
	}

	static List<Row> sorted(List<Row> rows)
	{
		List<Row> result = new ArrayList<>(rows);
		result.sort(Comparator.<Row, Integer>comparing(row -> row.kills, Comparator.nullsLast(Comparator.reverseOrder()))
			.thenComparing(row -> row.name, String.CASE_INSENSITIVE_ORDER));
		return result;
	}

	static List<String> uniqueNames(List<String> names)
	{
		Map<String, String> unique = new LinkedHashMap<>();
		for (String name : names)
		{
			if (name == null) continue;
			String clean = name.replace('\u00a0', ' ').trim();
			if (!clean.isEmpty()) unique.putIfAbsent(clean.toLowerCase(Locale.ROOT), clean);
		}
		return new ArrayList<>(unique.values());
	}
}

package com.bosskillmilestones;

final class GrindProgress
{
	static long nextMilestone(int kills)
	{
		return kills < 10 ? 10 : kills < 25 ? 25 : ((long) kills / 50 + 1) * 50;
	}

	static Integer total(String text)
	{
		try { return Integer.valueOf(text.replace("~", "").replace(",", "")); }
		catch (NumberFormatException ex) { return null; }
	}

	static String rival(FriendLeaderboard.View view, String own)
	{
		Integer kills = null;
		for (FriendLeaderboard.Row row : view.rows)
			if (sameName(row.name, own)) kills = row.kills;
		if (kills == null) return "Your public KC is unavailable";
		FriendLeaderboard.Row next = null;
		boolean incomplete = false;
		for (FriendLeaderboard.Row row : view.rows)
		{
			if (row.kills == null) incomplete = true;
			if (!sameName(row.name, own) && row.kills != null && row.kills >= kills
				&& (next == null || row.kills < next.kills)) next = row;
		}
		if (next == null) return incomplete ? "No rival in loaded results" : "You lead your friends!";
		return next.name + ": " + ((long) next.kills - kills + 1) + " to pass";
	}

	private static boolean sameName(String left, String right)
	{
		return right != null && left.replace('\u00a0', ' ').trim().equalsIgnoreCase(right.replace('\u00a0', ' ').trim());
	}
}

package com.bosskillmilestones;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/** Matches opposite signals one-to-one. Same-source kills remain separate. */
final class KillSignals
{
	static final int MATCH_TICKS = 8;
	private final List<Signal> signals = new ArrayList<>();

	boolean accept(String boss, boolean loot, int tick)
	{
		Iterator<Signal> iterator = signals.iterator();
		while (iterator.hasNext())
		{
			Signal signal = iterator.next();
			if (tick - signal.tick > MATCH_TICKS || tick < signal.tick)
			{
				iterator.remove();
			}
			else if (signal.boss.equals(boss) && signal.loot != loot)
			{
				iterator.remove();
				return false;
			}
		}
		signals.add(new Signal(boss, loot, tick));
		return true;
	}

	void clear()
	{
		signals.clear();
	}

	private static final class Signal
	{
		private final String boss;
		private final boolean loot;
		private final int tick;

		private Signal(String boss, boolean loot, int tick)
		{
			this.boss = boss;
			this.loot = loot;
			this.tick = tick;
		}
	}
}

package com.bosskillmilestones;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Singleton;
import javax.inject.Inject;
import net.runelite.client.audio.AudioPlayer;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
final class MilestoneAudio
{
	private ExecutorService worker;
	private final AudioPlayer audioPlayer;
	private int generation;

	@Inject
	MilestoneAudio(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	synchronized void start()
	{
		stop();
		worker = Executors.newSingleThreadExecutor(task -> {
			Thread thread = new Thread(task, "boss-milestone-audio");
			thread.setDaemon(true);
			return thread;
		});
	}

	synchronized void stop()
	{
		generation++;
		if (worker != null)
		{
			worker.shutdownNow();
			worker = null;
		}
	}

	static String resourceFor(int kills)
	{
		Celebration celebration = Celebration.select(kills, 0, 0, false);
		return celebration == null ? null : celebration.resource;
	}

	synchronized void play(Celebration celebration)
	{
		play(celebration, 100);
	}

	synchronized void play(Celebration celebration, int volumePercent)
	{
		int volume = Math.max(0, Math.min(100, volumePercent));
		if (worker == null || volume == 0) return;
		float gain = (float) (20 * Math.log10(volume / 100.0));
		int requestedGeneration = generation;
		worker.execute(() -> loadAndPlay(celebration.resource, requestedGeneration, gain));
	}

	private void loadAndPlay(String resource, int requestedGeneration, float gain)
	{
		synchronized (this)
		{
			if (worker == null || generation != requestedGeneration) return;
		}
		try
		{
			// Resource decoding and playback stay off the client thread. RuneLite owns
			// the audio line lifecycle; an already-started cue finishes naturally.
			audioPlayer.play(MilestoneAudio.class, resource, gain);
		}
		catch (Exception ex)
		{
			log.warn("Could not play milestone sound {}", resource, ex);
		}
	}
}

package com.bosskillmilestones;

import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;

/** Uses elapsed time so changing the system clock cannot extend or shorten visibility. */
final class OverlayActivity
{
	private final LongSupplier clock;
	private volatile Long lastKill;

	OverlayActivity(LongSupplier clock)
	{
		this.clock = clock;
	}

	void killed()
	{
		lastKill = clock.getAsLong();
	}

	void reset()
	{
		lastKill = null;
	}

	boolean visible(boolean alwaysOn, int timeoutMinutes)
	{
		Long last = lastKill;
		return alwaysOn || (last != null && clock.getAsLong() - last
			< TimeUnit.MINUTES.toNanos(Math.max(1, Math.min(60, timeoutMinutes))));
	}
}

