				assertEquals("WAVE", new String(bytes, 8, 4, StandardCharsets.US_ASCII));
				assertEquals("fmt ", new String(bytes, 12, 4, StandardCharsets.US_ASCII));
				assertEquals(16, header.getInt(16));
				assertEquals(1, header.getShort(20)); // PCM, no codec required
				assertEquals(2, header.getShort(22));
				assertEquals(44100, header.getInt(24));
				assertEquals(16, header.getShort(34));
				assertEquals("data", new String(bytes, 36, 4, StandardCharsets.US_ASCII));
				assertEquals(bytes.length - 44, header.getInt(40));
				assertTrue(header.getInt(40) > 0);
				assertTrue((double) header.getInt(40) / header.getInt(28) < 6);
			}
		}
	}

	@Test public void delegatesPlaybackAndIgnoresRequestsWhileStopped() throws Exception
	{
		LinkedBlockingQueue<String> requests = new LinkedBlockingQueue<>();
		AudioPlayer player = new AudioPlayer()
		{
			@Override public void play(Class<?> owner, String path, float gain)
			{
				requests.add(owner.getName() + ":" + path + ":" + gain);
			}
		};
		MilestoneAudio audio = new MilestoneAudio(player);
		try
		{
			audio.play(Celebration.TEN);
			assertTrue(requests.isEmpty());
			audio.start();
			audio.play(Celebration.GOAL);
			assertEquals(MilestoneAudio.class.getName() + ":" + Celebration.GOAL.resource + ":0.0",
				requests.poll(3, TimeUnit.SECONDS));
			audio.stop();
			audio.play(Celebration.THOUSAND);
			assertTrue(requests.isEmpty());
		}
		finally { audio.stop(); }
	}

	@Test public void legacyClipsAreNotPackaged()
	{
		assertNull(MilestoneAudio.class.getResource("/audio/birthday-party-horn.wav"));
		assertNull(MilestoneAudio.class.getResource("/audio/community-claps.wav"));
		assertNull(MilestoneAudio.class.getResource("/audio/wow-thats-amazing.wav"));
	}

	@Test public void volumeMutesAndScalesPlayback() throws Exception
	{
		LinkedBlockingQueue<Float> gains = new LinkedBlockingQueue<>();
		MilestoneAudio audio = new MilestoneAudio(new AudioPlayer()
		{
			@Override public void play(Class<?> owner, String path, float gain) { gains.add(gain); }
		});
		try
		{
			audio.start();
			audio.play(Celebration.TEN, 0);
			audio.play(Celebration.TEN, -10);
			audio.play(Celebration.GOAL, 50);
			Float half = gains.poll(3, TimeUnit.SECONDS);
			assertNotNull(half);
			assertEquals(-6.0206f, half, 0.001f);
			audio.play(Celebration.SESSION, 150);
			assertEquals(Float.valueOf(0f), gains.poll(3, TimeUnit.SECONDS));
			assertTrue(gains.isEmpty());
		}
		finally { audio.stop(); }
	}
}

package com.bosskillmilestones;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.bosskillmilestones.BossKillMilestonesConfig.MilestoneBasis.*;

public class MilestoneBasisTest
{
	@Test public void personalGoalsUseIndependentBasis()
	{
		BossKillMilestonesPlugin.Progress sessionGoal = new BossKillMilestonesPlugin.Progress("Sarachnis", 10, 125, "~1000", 25, ALL_TIME, SESSION);
		assertEquals(Integer.valueOf(1000), sessionGoal.milestoneCount());
		assertEquals(Integer.valueOf(10), sessionGoal.goalCount());
		assertEquals("10", sessionGoal.goalCountText());
		BossKillMilestonesPlugin.Progress savedGoal = new BossKillMilestonesPlugin.Progress("Sarachnis", 10, 125, "Unknown", 150, SESSION, SINCE_ACTIVATION);
		assertEquals(Integer.valueOf(125), savedGoal.goalCount());
		assertEquals("125", savedGoal.goalCountText());
		BossKillMilestonesPlugin.Progress legacy = new BossKillMilestonesPlugin.Progress("Sarachnis", 10, 125, "~1000", 1500);
		assertEquals(Integer.valueOf(1000), legacy.goalCount());
		assertEquals("~1000", legacy.goalCountText());
	}

	@Test public void sameKillUsesSelectedCounter()
	{
		assertEquals(Celebration.TEN, Celebration.select(SESSION.count(26, 10, 1250), 10, 0, false));
		assertEquals(Celebration.TWO_FIFTY, Celebration.select(ALL_TIME.count(26, 10, 1250), 10, 0, false));
		assertNull(Celebration.select(SINCE_ACTIVATION.count(26, 10, 1250), 10, 0, false));
	}

	@Test public void progressFollowsBasisWithoutChangingRecordedCounts()
	{
		BossKillMilestonesPlugin.Progress session = new BossKillMilestonesPlugin.Progress("Sarachnis", 9, 26, "~1249", 1300, SESSION);
		BossKillMilestonesPlugin.Progress lifetime = new BossKillMilestonesPlugin.Progress("Sarachnis", 9, 26, "~1249", 1300, ALL_TIME);
		assertEquals("1 away", session.nextMilestoneText());
		assertEquals("1 away", lifetime.nextMilestoneText());
		assertEquals(Integer.valueOf(1249), lifetime.milestoneCount());
		assertEquals(26, lifetime.saved);
		assertEquals(1300, lifetime.goal);
	}

	@Test public void unknownLifetimeDoesNotInventMilestoneProgress()
	{
		BossKillMilestonesPlugin.Progress progress = new BossKillMilestonesPlugin.Progress("Sarachnis", 9, 26, "Unknown", 0, ALL_TIME);
		assertNull(progress.milestoneCount());
		assertEquals("Sync lifetime total", progress.nextMilestoneText());
		assertEquals(Integer.valueOf(26), SINCE_ACTIVATION.count(26, 9, null));
	}
}

package com.bosskillmilestones;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.*;

public class OverlayActivityTest
{
	@Test
	public void requiresKillAndExpiresAtTimeout()
	{
		AtomicLong clock = new AtomicLong();
		OverlayActivity activity = new OverlayActivity(clock::get);
		assertFalse(activity.visible(false, 5));
		activity.killed();
		assertTrue(activity.visible(false, 5));
		clock.set(TimeUnit.MINUTES.toNanos(5) - 1);
		assertTrue(activity.visible(false, 5));
		clock.incrementAndGet();
		assertFalse(activity.visible(false, 5));
		activity.killed();
		assertTrue(activity.visible(false, 5));
	}

	@Test
	public void everyKillRefreshesTimerAndSettingsApplyImmediately()
	{
		AtomicLong clock = new AtomicLong();
		OverlayActivity activity = new OverlayActivity(clock::get);
		activity.killed();
		clock.set(TimeUnit.MINUTES.toNanos(4));
		activity.killed();
		clock.set(TimeUnit.MINUTES.toNanos(6));
		assertTrue(activity.visible(false, 5));
		assertFalse(activity.visible(false, 1));
		assertTrue(activity.visible(true, 1));
		assertFalse(activity.visible(false, 1));
	}

	@Test
	public void resetHidesUntilNewKillUnlessAlwaysOn()
	{
		OverlayActivity activity = new OverlayActivity(() -> 100L);
		assertTrue(activity.visible(true, 5));
		activity.killed();
		activity.reset();
		assertFalse(activity.visible(false, 5));
		assertTrue(activity.visible(true, 5));
	}
}

